function badgeSubsets(badges) {
  const all = [];
  for (let mask = 0; mask < 1 << badges.length; mask++)
    all.push(badges.filter((_, i) => mask & (1 << i)).sort((a, b) => a - b));
  return all.sort((x, y) => {
    if (x.length !== y.length) return x.length - y.length;
    for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return x[i] - y[i];
    return 0;
  });
}

function badgeSubsets(badges) {
  const sorted = [...badges].sort((a, b) => a - b);
  const result = [];
  const picked = [];
  const choose = (start, size) => {
    if (picked.length === size) { result.push([...picked]); return; }
    for (let i = start; i <= sorted.length - (size - picked.length); i++) {
      picked.push(sorted[i]);
      choose(i + 1, size);
      picked.pop();
    }
  };
  for (let size = 0; size <= sorted.length; size++) choose(0, size);
  return result;
}
